
/// Categories of detected Flutter / Dart test and runtime failures.
enum FailureCategory {
  renderFlexOverflowHorizontal,
  renderFlexOverflowVertical,
  unboundedConstraints,
  pumpAndSettleTimeout,
  missingPlugin,
  assertionFailure,
  generalException,
  unknown;

  String get id => name;
}

/// A structured, actionable directive generated by the heuristic engine.
class HeuristicDirective {
  final FailureCategory category;
  final String title;
  final String summary;
  final List<String> actionableFixes;
  final String? codeSnippet;

  const HeuristicDirective({
    required this.category,
    required this.title,
    required this.summary,
    required this.actionableFixes,
    this.codeSnippet,
  });

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('[$title]');
    buffer.writeln(summary);
    if (actionableFixes.isNotEmpty) {
      buffer.writeln('\nActionable directives:');
      for (var i = 0; i < actionableFixes.length; i++) {
        buffer.writeln('  ${i + 1}. ${actionableFixes[i]}');
      }
    }
    if (codeSnippet != null && codeSnippet!.trim().isNotEmpty) {
      buffer.writeln('\nCode Directive:\n${codeSnippet!.trim()}');
    }
    return buffer.toString().trim();
  }
}

/// Information about the error location extracted from test outputs.
class LocationInfo {
  final String filePath;
  final int line;
  final int? column;

  const LocationInfo({
    required this.filePath,
    required this.line,
    this.column,
  });

  @override
  String toString() => '$filePath:$line${column != null ? ':$column' : ''}';
}

/// Comprehensive analysis result produced by [Heuristics.analyze].
class HeuristicAnalysisResult {
  final FailureCategory category;
  final HeuristicDirective directive;
  final LocationInfo? location;
  final String errorSignature;
  final String rawOutput;

  const HeuristicAnalysisResult({
    required this.category,
    required this.directive,
    required this.location,
    required this.errorSignature,
    required this.rawOutput,
  });
}

/// Deterministic heuristic engine for Flutter test failures.
class Heuristics {
  /// Regular expressions for detecting error patterns
  static final RegExp _overflowRightOrLeft = RegExp(
    r'RenderFlex overflowed by [0-9\.]+ pixels on the (right|left)',
    caseSensitive: false,
  );

  static final RegExp _overflowBottomOrTop = RegExp(
    r'RenderFlex overflowed by [0-9\.]+ pixels on the (bottom|top)',
    caseSensitive: false,
  );

  static final RegExp _unboundedViewport = RegExp(
    r'(viewport was given unbounded (height|width)|RenderFlex children have non-zero flex but incoming (height|width) constraints are unbounded|unbounded (height|width) constraint)',
    caseSensitive: false,
  );

  static final RegExp _pumpAndSettleTimeout = RegExp(
    r'pumpAndSettle timed out',
    caseSensitive: false,
  );

  static final RegExp _missingPlugin = RegExp(
    r'MissingPluginException\((?:No implementation found for method ([^\s]+) on channel ([^\s\)]+)|.*)\)',
    caseSensitive: false,
  );

  static final RegExp _missingPluginGeneric = RegExp(
    r'MissingPluginException|No implementation found for method .* on channel',
    caseSensitive: false,
  );

  /// Detect the failure category and formulate the actionable heuristic directive.
  static HeuristicDirective? detect(String rawOutput) {
    if (rawOutput.isEmpty) return null;

    // 1. pumpAndSettle timed out
    if (_pumpAndSettleTimeout.hasMatch(rawOutput)) {
      return pumpAndSettleTimeout();
    }

    // 2. MissingPluginException
    if (_missingPluginGeneric.hasMatch(rawOutput)) {
      final match = _missingPlugin.firstMatch(rawOutput);
      final method = match?.group(1);
      final channel = match?.group(2);
      return missingPlugin(channel: channel, method: method);
    }

    // 3. Unbounded constraints (ListView, Viewport)
    if (_unboundedViewport.hasMatch(rawOutput) ||
        (rawOutput.contains('unbounded') &&
            (rawOutput.contains('ListView') ||
                rawOutput.contains('viewport') ||
                rawOutput.contains('RenderViewport')))) {
      final isListView = rawOutput.contains('ListView');
      return unboundedConstraints(widgetName: isListView ? 'ListView' : null);
    }

    // 4. RenderFlex Horizontal Overflow (Row, right/left)
    if (_overflowRightOrLeft.hasMatch(rawOutput) ||
        (rawOutput.contains('RenderFlex overflowed') &&
            (rawOutput.contains('right') ||
                rawOutput.contains('left') ||
                rawOutput.contains('Row') ||
                rawOutput.contains('horizontal')))) {
      return renderFlexHorizontal();
    }

    // 5. RenderFlex Vertical Overflow (Column, bottom/top)
    if (_overflowBottomOrTop.hasMatch(rawOutput) ||
        (rawOutput.contains('RenderFlex overflowed') &&
            (rawOutput.contains('bottom') ||
                rawOutput.contains('top') ||
                rawOutput.contains('Column') ||
                rawOutput.contains('vertical')))) {
      return renderFlexVertical();
    }

    // 6. Generic RenderFlex fallback
    if (rawOutput.contains('RenderFlex overflowed')) {
      if (rawOutput.contains('Column')) {
        return renderFlexVertical();
      }
      return renderFlexHorizontal();
    }

    // 7. General Assertion Failure
    if (rawOutput.contains('Expected:') && rawOutput.contains('Actual:')) {
      return assertionFailure();
    }

    return null;
  }

  /// Analyze raw output completely, extracting category, directive, location, and signature.
  static HeuristicAnalysisResult analyze(
    String rawOutput, {
    String? fallbackFilePath,
    int? fallbackLine,
  }) {
    final directive = detect(rawOutput) ?? genericFallback();
    final location = extractLocation(rawOutput) ??
        (fallbackFilePath != null
            ? LocationInfo(filePath: fallbackFilePath, line: fallbackLine ?? 0)
            : null);
    final errorSignature = extractErrorSignature(rawOutput, directive.category);

    return HeuristicAnalysisResult(
      category: directive.category,
      directive: directive,
      location: location,
      errorSignature: errorSignature,
      rawOutput: rawOutput,
    );
  }

  /// Formulate directive for horizontal RenderFlex overflow (typically Row).
  static HeuristicDirective renderFlexHorizontal({String? widgetName}) {
    return const HeuristicDirective(
      category: FailureCategory.renderFlexOverflowHorizontal,
      title: 'RenderFlex Horizontal Overflow',
      summary:
          'A RenderFlex overflowed horizontally. The row or horizontal flex children exceed the available width.',
      actionableFixes: [
        'Wrap the overflowing child widget (e.g. Text, Container, Image) with `Expanded` or `Flexible`.',
        'Wrap the `Row` with `SingleChildScrollView(scrollDirection: Axis.horizontal, child: Row(...))` if horizontal scrolling is intended.',
        'Replace the `Row` with `Wrap(direction: Axis.horizontal, spacing: 8.0, children: [...])` to allow children to wrap to multiple lines.',
      ],
      codeSnippet: '''
// Option 1: Wrap flexible child with Expanded
Row(
  children: [
    Expanded(child: Text(longText)),
  ],
)

// Option 2: Allow horizontal scrolling
SingleChildScrollView(
  scrollDirection: Axis.horizontal,
  child: Row(children: [...]),
)

// Option 3: Use Wrap
Wrap(
  direction: Axis.horizontal,
  spacing: 8.0,
  children: [...],
)''',
    );
  }

  /// Formulate directive for vertical RenderFlex overflow (typically Column).
  static HeuristicDirective renderFlexVertical({String? widgetName}) {
    return const HeuristicDirective(
      category: FailureCategory.renderFlexOverflowVertical,
      title: 'RenderFlex Vertical Overflow',
      summary:
          'A RenderFlex overflowed vertically. The column or vertical flex children exceed the available screen/parent height.',
      actionableFixes: [
        'Wrap the dynamic/expanding child widget with `Expanded` or `Flexible`.',
        'Wrap the `Column` with `SingleChildScrollView(child: Column(...))` to enable vertical scrolling.',
        'Replace the `Column` with `ListView(children: [...])`.',
      ],
      codeSnippet: '''
// Option 1: Wrap child in Expanded
Column(
  children: [
    Expanded(child: AnyLargeOrDynamicWidget()),
  ],
)

// Option 2: Scrollable Column
SingleChildScrollView(
  child: Column(children: [...]),
)

// Option 3: Replace Column with ListView
ListView(
  children: [...],
)''',
    );
  }

  /// Formulate directive for unbounded constraints (typically ListView inside Column or unbounded Viewport).
  static HeuristicDirective unboundedConstraints({String? widgetName}) {
    final name = widgetName ?? 'ListView';
    return HeuristicDirective(
      category: FailureCategory.unboundedConstraints,
      title: 'Unbounded Viewport / $name Constraints',
      summary:
          'A scrollable view ($name) was placed inside an unbounded parent without height/width constraints (e.g. inside a Column or another scrollable).',
      actionableFixes: [
        'Wrap the `$name` with `Expanded(child: $name(...))` or `Flexible` if placed inside a Column or Row.',
        'If the list has a small, finite number of items and should not scroll independently, set `shrinkWrap: true` and `physics: const NeverScrollableScrollPhysics()` on `$name`.',
        'Wrap the `$name` with `SizedBox(height: <height>, child: $name(...))` or `ConstrainedBox` to establish bounded constraints.',
      ],
      codeSnippet: '''
// Option 1: Wrap with Expanded inside Column/Row
Column(
  children: [
    Expanded(
      child: ListView.builder(
        itemCount: items.length,
        itemBuilder: (context, index) => ItemTile(items[index]),
      ),
    ),
  ],
)

// Option 2: Use shrinkWrap with NeverScrollableScrollPhysics
ListView(
  shrinkWrap: true,
  physics: const NeverScrollableScrollPhysics(),
  children: [...],
)

// Option 3: Fixed height container
SizedBox(
  height: 300,
  child: ListView(...),
)''',
    );
  }

  /// Formulate directive for pumpAndSettle timed out.
  static HeuristicDirective pumpAndSettleTimeout() {
    return const HeuristicDirective(
      category: FailureCategory.pumpAndSettleTimeout,
      title: 'pumpAndSettle Timed Out',
      summary:
          '`tester.pumpAndSettle()` timed out because active animations, continuous microtasks, or pending timers are scheduling infinite frames.',
      actionableFixes: [
        'Replace `await tester.pumpAndSettle();` with discrete `await tester.pump();` or `await tester.pump(const Duration(milliseconds: 100));`.',
        'Check for infinite animations (e.g. `CircularProgressIndicator`, `LinearProgressIndicator`, looping `AnimationController`) and avoid calling `pumpAndSettle()` while they are running.',
        'If waiting for an asynchronous state change, use a discrete loop: `for (int i = 0; i < 10; i++) { await tester.pump(const Duration(milliseconds: 100)); }`.',
        'Verify if an uncompleted Stream, Future, or periodic timer (`Timer.periodic`) is left unclosed.',
      ],
      codeSnippet: '''
// Discrete pumping instead of pumpAndSettle
await tester.pump();
await tester.pump(const Duration(milliseconds: 100));

// Or pump a finite duration
await tester.pump(const Duration(seconds: 1));

// If waiting for a widget under test with infinite animation (e.g. CircularProgressIndicator):
// Do NOT call pumpAndSettle(). Call pump() instead.
expect(find.byType(CircularProgressIndicator), findsOneWidget);
await tester.pump(const Duration(milliseconds: 500));''',
    );
  }

  /// Formulate directive for MissingPluginException / unmocked platform channels.
  static HeuristicDirective missingPlugin({String? channel, String? method}) {
    final channelName = channel ?? '<channel_name>';
    final methodName = method ?? '<method_name>';

    final snippet = '''
// Mock platform channel in test setUp() or before widget pumping:
TestWidgetsFlutterBinding.ensureInitialized();
TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
    .setMockMethodCallHandler(
  const MethodChannel('$channelName'),
  (MethodCall methodCall) async {
    if (methodCall.method == '$methodName') {
      return null; // Return mock value expected by the plugin
    }
    return null;
  },
);

// If using shared_preferences:
// SharedPreferences.setMockInitialValues({});''';

    return HeuristicDirective(
      category: FailureCategory.missingPlugin,
      title: 'MissingPluginException / Unmocked Platform Channel',
      summary:
          'A platform channel call was made during testing without a mock handler registered ($channelName -> $methodName).',
      actionableFixes: [
        'Ensure `TestWidgetsFlutterBinding.ensureInitialized();` is invoked before setting up mocks.',
        'Register a mock handler using `TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger.setMockMethodCallHandler(MethodChannel(\'$channelName\'), ...)`.',
        'If this is a known plugin like `shared_preferences`, call `SharedPreferences.setMockInitialValues({})` in `setUp()`.',
        'If using `path_provider`, mock `$channelName` to return a temporary directory path string.',
      ],
      codeSnippet: snippet,
    );
  }

  /// Directive for generic assertion failures.
  static HeuristicDirective assertionFailure() {
    return const HeuristicDirective(
      category: FailureCategory.assertionFailure,
      title: 'Assertion / Expectation Failure',
      summary: 'A test assertion or expectation condition failed.',
      actionableFixes: [
        'Compare the Expected value against the Actual value in the test output.',
        'Verify if widget state has settled before checking `expect(...)` using `await tester.pump();`.',
        'Verify finder criteria (e.g., `find.text`, `find.byType`, `find.byKey`).',
      ],
    );
  }

  /// Fallback directive for unrecognized errors.
  static HeuristicDirective genericFallback() {
    return const HeuristicDirective(
      category: FailureCategory.unknown,
      title: 'Test Failure',
      summary: 'An error occurred during test execution.',
      actionableFixes: [
        'Inspect the stack trace to locate the exact failing line.',
        'Verify whether required dependencies or platform channels are initialized.',
        'Revert recent changes if the issue was introduced by an incremental edit.',
      ],
    );
  }

  /// Extract the source location (file path and line) from Flutter error output.
  static LocationInfo? extractLocation(String rawOutput) {
    if (rawOutput.isEmpty) return null;

    // Pattern 1: "The relevant error-causing widget was: ... (file:///...:line:col)"
    final relevantWidgetRegex = RegExp(
      r'The relevant error-causing widget was:[\s\S]*?(?:file:///?|package:[^/]+/)?([a-zA-Z0-9_\-\./\\]+\.dart):(\d+)(?::(\d+))?',
      caseSensitive: false,
    );
    final matchWidget = relevantWidgetRegex.firstMatch(rawOutput);
    if (matchWidget != null) {
      final file = matchWidget.group(1)!;
      final line = int.tryParse(matchWidget.group(2)!) ?? 0;
      final col = matchWidget.group(3) != null
          ? int.tryParse(matchWidget.group(3)!)
          : null;
      if (!file.contains('flutter/src/') && !file.contains('flutter_test/')) {
        return LocationInfo(filePath: file, line: line, column: col);
      }
    }

    // Pattern 2: Stack trace lines prioritizing test/ or lib/ files
    // e.g. #0      ... (file:///C:/path/lib/my_file.dart:42:10)
    // or   test/my_test.dart:42:10
    final stackTraceRegex = RegExp(
      r'(?:file:///?|package:[^/]+/)?([a-zA-Z0-9_\-\./\\]+\.dart)(?::|\s+)(\d+)(?::(\d+))?',
      caseSensitive: false,
    );

    final allMatches = stackTraceRegex.allMatches(rawOutput);
    LocationInfo? fallbackLocation;

    for (final match in allMatches) {
      final file = match.group(1)!;
      final line = int.tryParse(match.group(2)!) ?? 0;
      final col =
          match.group(3) != null ? int.tryParse(match.group(3)!) : null;

      // Skip framework internals
      if (file.contains('flutter/src/') ||
          file.contains('flutter_test/') ||
          file.contains('dart:') ||
          file.contains('package:flutter/')) {
        continue;
      }

      final info = LocationInfo(filePath: file, line: line, column: col);
      // Prefer application source or test files
      if (file.contains('lib/') || file.contains('test/')) {
        return info;
      }
      fallbackLocation ??= info;
    }

    return fallbackLocation;
  }

  /// Extract a normalized error signature suitable for deterministic fingerprinting.
  static String extractErrorSignature(
    String rawOutput,
    FailureCategory category,
  ) {
    switch (category) {
      case FailureCategory.renderFlexOverflowHorizontal:
        return 'renderflex overflowed on the right/left';
      case FailureCategory.renderFlexOverflowVertical:
        return 'renderflex overflowed on the bottom/top';
      case FailureCategory.unboundedConstraints:
        if (rawOutput.contains('ListView')) {
          return 'unbounded viewport constraints in listview';
        }
        return 'unbounded viewport constraints';
      case FailureCategory.pumpAndSettleTimeout:
        return 'pumpandsettle timed out';
      case FailureCategory.missingPlugin:
        final match = _missingPlugin.firstMatch(rawOutput);
        final method = match?.group(1) ?? 'any';
        final channel = match?.group(2) ?? 'any';
        return 'missingpluginexception:channel=$channel:method=$method';
      case FailureCategory.assertionFailure:
        // Extract expected vs actual if present
        final expMatch = RegExp(r'Expected: (.*)').firstMatch(rawOutput);
        final actMatch = RegExp(r'Actual: (.*)').firstMatch(rawOutput);
        if (expMatch != null && actMatch != null) {
          final exp = expMatch.group(1)?.trim();
          final act = actMatch.group(1)?.trim();
          return 'assertion failure: expected $exp but was $act';
        }
        return 'assertion failure';
      case FailureCategory.generalException:
      case FailureCategory.unknown:
        // Extract first line of error or exception
        final lines = rawOutput
            .split('\n')
            .map((l) => l.trim())
            .where((l) => l.isNotEmpty && !l.startsWith('══╡'))
            .toList();
        if (lines.isNotEmpty) {
          final first = lines.first;
          return first.length > 80 ? first.substring(0, 80) : first;
        }
        return 'unknown error';
    }
  }
}
